WITH metrics_long AS (SELECT * FROM (SELECT id, supplier_id, cost, price FROM products) src UNPIVOT (value FOR measure IN (cost, price))) SELECT supplier_id, SUM(CASE WHEN measure = 'cost' THEN value ELSE 0 END) AS cost_value, COUNT(*) FILTER (WHERE measure = 'price') AS price_rows, SIZE(COLLECT_SET(measure)) AS num_measures, AVG(value) FILTER (WHERE measure = 'price') AS price_avg_value, ROUND(AVG(value), 2) AS avg_value FROM metrics_long GROUP BY supplier_id HAVING price_rows < 1000
